/**
 * generated by stackra gen from src/config/seo.config.ts (robots) and src/config/site.config.ts
 * (previewHostPrefixes) — do not edit
 * Purpose: `/robots.txt` per site: allow everything with the configured disallows and the sitemap
 *          link on a live site; disallow everything on a preview host or a sandbox tenant.
 * Boundary: the disallow list is the config's, read from the container per request.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { robotsTxt } from "@stackra/seo/robots";
import type { Route } from "./+types/robots.route";
import { SeoConfig } from "#src/config/seo.config";
import { resolveSite } from "#src/server/resolve-site.server";

export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args);
  const site = await resolveSite(ctx);
  const body = site.indexable
    ? robotsTxt({
        allow: ["/"],
        disallow: ctx.config(SeoConfig).disallow,
        sitemap: `${site.origin}/sitemap.xml`,
      })
    : robotsTxt({ disallow: ["/"] });
  return new Response(body, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
